	/**
	 * Method to retrieve the LeavePolicy via LeavePolicyFetchOneSummary
	 * @param 	summary LeavePolicyFetchOneSummary
	 * @return 	LeavePolicyFetchOneResponse
	 */
	public LeavePolicy getLeavePolicy( LeavePolicyFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "LeavePolicyFetchOneSummary arg cannot be null" );

		LeavePolicy entity = null;
		UUID id = summary.getLeavePolicyId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a LeavePolicy using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


